    <script>function todoForm(){return {subjectType:@js(old('subject_type', $todo->subject_type ?? 'lead')),subjectId:@js(old('subject_id', $todo->subject_id)),taskWith:@js(old('task_with', $todo->task_with)),subjects:[],init(){this.loadSubjects()},async loadSubjects(clear=false){if(clear){this.subjectId='';this.taskWith=''}this.subjects=await (await fetch('{{ route('todos.subjects') }}?type='+this.subjectType)).json()},setTaskWith(){this.taskWith=this.subjects.find(x=>String(x.id)===String(this.subjectId))?.label||''}}}</script>
